import 'package:firebase_core/firebase_core.dart';
import 'package:firebase_messaging/firebase_messaging.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'core/theme/app_theme.dart';
import 'router.dart';

// Generated by `flutterfire configure`. If you use google-services.json only, delete the options arg.
import 'firebase_options.dart';

@pragma('vm:entry-point')
Future<void> _bgHandler(RemoteMessage m) async => Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);
  FirebaseMessaging.onBackgroundMessage(_bgHandler);
  await FirebaseMessaging.instance.requestPermission();
  runApp(const ProviderScope(child: UrbanEyeApp()));
}

class UrbanEyeApp extends ConsumerWidget {
  const UrbanEyeApp({super.key});
  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final router = ref.watch(routerProvider);
    // US-63: tapping a push opens the report.
    FirebaseMessaging.onMessageOpenedApp.listen((m) {
      final id = m.data['reportId'];
      if (id != null) router.push('/report/$id');
    });
    return MaterialApp.router(title: 'UrbanEye', theme: AppTheme.light, routerConfig: router, debugShowCheckedModeBanner: false);
  }
}
